package com.bank.contrib.service;

import com.bank.contrib.model.Contribution;
import java.util.logging.*;

// Mimics the Skara bots: enforce governance before integration.
public class ContributionGate {
    private static final Logger log = Logger.getLogger(ContributionGate.class.getName());
    private static final int REQUIRED_REVIEWERS = 1;  // area-specific rule

    public boolean canIntegrate(Contribution c) {
        if (!c.agreementSigned()) {                        // agreement check (bot)
            log.warning(() -> "Blocked: " + c.author() + " has not signed the contributor agreement");
            return false;
        }
        if (c.issueId() == null || c.issueId().isBlank()) { // issue-link check (bot)
            log.warning(() -> "Blocked: no linked issue id for change by " + c.author());
            return false;
        }
        if (c.approvals().size() < REQUIRED_REVIEWERS) {    // reviewer-count check (bot)
            log.warning(() -> "Blocked: needs " + REQUIRED_REVIEWERS
                    + " reviewer(s), has " + c.approvals().size());
            return false;
        }
        return true;
    }

    public void integrate(Contribution c) {                 // the /integrate command (bot)
        if (canIntegrate(c)) {
            log.info(() -> "Integrated change " + c.issueId() + " by " + c.author()
                    + " (approved by " + c.approvals() + ")");
        } else {
            log.severe(() -> "Integration refused for change by " + c.author());
        }
    }
}
