package com.bank.contrib;

import com.bank.contrib.model.Contribution;
import com.bank.contrib.service.ContributionGate;
import java.util.*;
import java.util.logging.*;

public class GateDemo {
    private static final Logger log = Logger.getLogger(GateDemo.class.getName());

    static {
        LogManager.getLogManager().reset();
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        var gate = new ContributionGate();

        // Rajesh proposes a change: agreement signed, ticket linked, Priya approved.
        var good = new Contribution("Rajesh", true, "NBI-1234", List.of("Priya"));
        gate.integrate(good);

        // A change missing the signed agreement — blocked, just like a Skara bot would.
        var noAgreement = new Contribution("NewJoiner", false, "NBI-1235", List.of("Priya"));
        gate.integrate(noAgreement);

        // A change with no reviewers yet — blocked until review completes.
        var noReview = new Contribution("Rajesh", true, "NBI-1236", List.of());
        gate.integrate(noReview);
    }
}
